const fetch = require("node-fetch");
const fs = require("fs");

const MINT_URL = "https://staging.crossmint.com/api/2022-06-09/collections/default/nfts";
const ACTION_URL_BASE = "https://staging.crossmint.com/api/2022-06-09/actions";
const POLL_INTERVAL_MS = 2000;
const MAX_ATTEMPTS = 5;
const MINT_CHAIN = "polygon-amoy";

const apiKey = process.env.CROSSMINT_API_KEY;

async function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function mintNft() {
  const payload = {
    recipient: `email:demo@example.com:${MINT_CHAIN}`,
    metadata: {
      name: "Poll Test NFT",
      description: "Testing async polling",
      image: "https://example.com/poll.png",
    },
  };

  const response = await fetch(MINT_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": apiKey,
    },
    body: JSON.stringify(payload),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Mint request failed (${response.status}): ${errorText}`);
  }

  return response.json();
}

async function pollAction(actionId) {
  let status = "pending";
  let attempts = 0;

  while (attempts < MAX_ATTEMPTS && status === "pending") {
    attempts += 1;

    const response = await fetch(`${ACTION_URL_BASE}/${actionId}`, {
      method: "GET",
      headers: {
        "x-api-key": apiKey,
      },
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Polling failed (${response.status}): ${errorText}`);
    }

    const data = await response.json();
    status = data?.status ?? status;

    if (status === "pending" && attempts < MAX_ATTEMPTS) {
      await sleep(POLL_INTERVAL_MS);
    }
  }

  return { status, attempts };
}

async function writeResult(result) {
  fs.writeFileSync("/home/user/poll_result.json", JSON.stringify(result, null, 2));
}

